select
  id, score_min, score_max, result_level, result_description, daily_advice, professional_advice, emergency_contact
from mental_health_evaluation


        and id = #{id}


        and score_min = #{scoreMin}


        and score_max = #{scoreMax}


        and result_level = #{resultLevel}


        and result_description = #{resultDescription}


        and daily_advice = #{dailyAdvice}


        and professional_advice = #{professionalAdvice}


        and emergency_contact = #{emergencyContact}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from mental_health_evaluation


        and id = #{id}


        and score_min = #{scoreMin}


        and score_max = #{scoreMax}


        and result_level = #{resultLevel}


